package com.networkzero.screens;

import com.badlogic.gdx.*;
import com.badlogic.gdx.graphics.*;
import com.badlogic.gdx.graphics.g2d.*;
import com.badlogic.gdx.graphics.glutils.ShapeRenderer;
import com.badlogic.gdx.math.Vector2;
import com.badlogic.gdx.utils.ScreenUtils;
import com.badlogic.gdx.utils.viewport.FitViewport;
import com.networkzero.GameMode;
import com.networkzero.engine.SettingsManager;
import com.networkzero.net.*;
import com.networkzero.room.GameState;
import com.networkzero.session.*;
import com.networkzero.story.StoryScreen;
import java.net.*;

/** LAN host/join lobby with a small, fixed-layout UI. */
public final class LobbyScreen implements Screen {
    private static final float W=1920,H=1080;
    private final Game game;private final GameMode mode;private final FitViewport viewport=new FitViewport(W,H);private final SpriteBatch batch=new SpriteBatch();private final ShapeRenderer shapes=new ShapeRenderer();private final BitmapFont font=new BitmapFont();private final SettingsManager settings=new SettingsManager();
    private final String localIp;private volatile GameSession session;private volatile String status="",address="",hostFound="";private volatile boolean connected,connecting,hostReady,clientReady,storyStarted,hostStoryDone,clientStoryDone,roomStarted,roomBeginReceived,discoveryBusy,editingName;private float discoveryTimer;private long toastUntil;private String toast="";
    public LobbyScreen(Game game,GameMode mode){this.game=game;this.mode=mode;settings.load();CoopRules.load();localIp=findLanIp();font.getData().setScale(1.45f);if(mode==GameMode.HOST)startHost();}
    private void startHost(){try{HostSession h=new HostSession(new GameState(),settings.playerName,null);session=h;h.setNetworkListener(this::hostMessage);status="Waiting for player 2...";}catch(Exception e){status="Could not host: "+e.getMessage();}}
    private void findOrCreateHost(){if(session instanceof HostSession)return;startHost();}
    private void saveName(){String s=settings.playerName.trim();settings.playerName=s.isEmpty()?"Player":s;settings.save();}
    private String findLanIp(){try{for(NetworkInterface ni:java.util.Collections.list(NetworkInterface.getNetworkInterfaces()))if(ni.isUp()&&!ni.isLoopback())for(InetAddress a:java.util.Collections.list(ni.getInetAddresses()))if(a instanceof Inet4Address&&a.isSiteLocalAddress())return a.getHostAddress();}catch(Exception ignored){}return "Unavailable";}
    private void hostMessage(Object m){if(m instanceof Network.Ready r){clientReady=r.ready;status=clientReady?"Both players connected.":"Waiting for player 2...";}else if(m instanceof Network.RoomReady){clientStoryDone=true;if(hostStoryDone)beginRoom();}else if(m instanceof Network.PartnerLeft){connected=false;clientReady=false;status="Player disconnected.";}}
    private void clientMessage(Object m){if(m instanceof Network.Welcome){connecting=false;connected=true;status="Connected. Ready when you are.";if(session.state().roomNumber==3){roomStarted=true;game.setScreen(new Room3Screen(game,session,true));}else if(session.state().paused||session.state().secondsLeft<2700||!session.state().inventory.isEmpty()||!session.state().solved.isEmpty())enterRoom();}else if(m instanceof Network.Reject r){connecting=false;status=r.reason;connected=false;}else if(m instanceof Network.GameEvent e){if("START_STORY".equals(e.name))startStory();else if("ROOM_BEGIN".equals(e.name)){roomBeginReceived=true;enterRoom();}else if("ROOM3_BEGIN".equals(e.name)){roomStarted=true;game.setScreen(new Room3Screen(game,session,false));}}else if(m instanceof Network.PartnerLeft){connecting=false;status="Host left the game.";connected=false;}else if(m instanceof String s&&s.equals("HOST_LEFT")){connecting=false;status="Host left the game.";connected=false;}}
    private void connect(){if(connecting||connected)return;if(address.isBlank()){status="Enter a host IP address.";return;}connecting=true;status="Connecting...";RemoteSession r=new RemoteSession(settings.playerName,this::clientMessage);session=r;String target=address.trim();new Thread(()->{try{r.connect(target,5000);}catch(Exception e){String detail=e.getMessage();if(detail==null||detail.isBlank())detail=e.getClass().getSimpleName();String error=detail;Gdx.app.postRunnable(()->{if(session==r){connecting=false;connected=false;status="Could not connect to "+target+": "+error;}});}} ,"network-connect").start();}
    private void discover(){if(discoveryBusy)return;discoveryBusy=true;new Thread(()->{try{InetAddress a=Network.discover(900);hostFound=a==null?"":a.getHostAddress();if(!hostFound.isEmpty()&&address.isEmpty())address=hostFound;}catch(Exception ignored){hostFound="";}finally{discoveryBusy=false;}} ,"network-discovery").start();}
    private void startStory(){if(storyStarted)return;storyStarted=true;if(session.isHost())session.send(new Network.GameEvent("START_STORY",""));game.setScreen(new StoryScreen(game,session,()->storyDone()));}
    private void storyDone(){if(session==null)return;if(session.isHost()){hostStoryDone=true;if(clientStoryDone||!connected)beginRoom();}else{session.send(new Network.RoomReady());if(roomBeginReceived)enterRoom();}}
    private void beginRoom(){if(roomStarted)return;roomStarted=true;if(session instanceof HostSession h)h.send(new Network.GameEvent("ROOM_BEGIN",""));game.setScreen(new RoomScreen(game,session,false));}
    private void enterRoom(){if(roomStarted)return;roomStarted=true;game.setScreen(new RoomScreen(game,session,false));}
    private void leave(){GameSession current=session;session=null;if(current!=null)current.close();game.setScreen(new LandingScreen(game));}
    @Override public void show(){Gdx.input.setInputProcessor(new InputAdapter(){@Override public boolean keyTyped(char c){if(editingName){if(c>=32&&c<127&&settings.playerName.length()<16){settings.playerName+=c;return true;}return false;}if(mode==GameMode.JOIN&&c>=32&&c<127&&address.length()<64){address+=c;return true;}return false;}@Override public boolean keyDown(int k){if(editingName){if(k==Input.Keys.BACKSPACE&&!settings.playerName.isEmpty()){settings.playerName=settings.playerName.substring(0,settings.playerName.length()-1);return true;}if(k==Input.Keys.ENTER||k==Input.Keys.ESCAPE){editingName=false;saveName();return true;}return false;}if(k==Input.Keys.BACKSPACE&&mode==GameMode.JOIN&&!address.isEmpty()){address=address.substring(0,address.length()-1);return true;}if(k==Input.Keys.ESCAPE){leave();return true;}if(k==Input.Keys.ENTER&&mode==GameMode.JOIN){connect();return true;}return false;}@Override public boolean touchDown(int sx,int sy,int p,int b){Vector2 v=viewport.unproject(new Vector2(sx,sy));float x=v.x,y=v.y;if(x>=350&&x<=900&&y>=735&&y<=785){editingName=!editingName;if(!editingName)saveName();return true;}if(editingName){editingName=false;saveName();}if(y>365&&y<485){if(x>430&&x<850){if(mode==GameMode.JOIN){if(!connected)connect();else{clientReady=!clientReady;session.send(new Network.Ready(clientReady));status=clientReady?"Ready. Waiting for host...":"Not ready.";}}else if(session instanceof HostSession h&&h.partnerConnected()){hostReady=!hostReady;status=hostReady?"Ready.":"Not ready.";}}else if(x>=900&&session instanceof HostSession h&&hostReady&&h.clientReady())startStory();}else if(y>510&&y<600&&mode==GameMode.JOIN){address=hostFound;}else if(y<315&&x<800)leave();return true;}});if(mode==GameMode.JOIN)discover();}
    @Override public void render(float delta){discoveryTimer+=Math.min(delta,.1f);if(mode==GameMode.JOIN&&discoveryTimer>=2){discoveryTimer=0;discover();}if(session instanceof HostSession h){connected=h.partnerConnected();h.tick(delta);}else if(session instanceof RemoteSession r)r.tick();ScreenUtils.clear(.015f,.02f,.035f,1);viewport.apply();batch.setProjectionMatrix(viewport.getCamera().combined);shapes.setProjectionMatrix(viewport.getCamera().combined);shapes.begin(ShapeRenderer.ShapeType.Filled);shapes.setColor(.035f,.045f,.065f,1);shapes.rect(240,170,1440,740);shapes.end();shapes.begin(ShapeRenderer.ShapeType.Line);shapes.setColor(1,.45f,.12f,1);shapes.rect(240,170,1440,740);shapes.end();batch.begin();font.setColor(Color.ORANGE);font.draw(batch,mode==GameMode.HOST?"HOST CO-OP (LAN)":"JOIN CO-OP (LAN)",330,825);font.setColor(editingName?Color.ORANGE:Color.WHITE);font.draw(batch,"Your name: "+settings.playerName+(editingName?"_":"  [CLICK TO EDIT]"),360,760);font.setColor(Color.WHITE);if(mode==GameMode.HOST){font.draw(batch,"LAN address: "+localIp+":"+Network.TCP_PORT,360,680);font.draw(batch,connected?"Player 2: "+session.partnerName():"Waiting for player 2...",360,600);font.draw(batch,hostReady?"READY":"READY UP",500,430);if(connected&&((HostSession)session).clientReady())font.draw(batch,"START",930,430);}else{font.draw(batch,"Found host: "+(hostFound.isEmpty()?"searching...":hostFound),360,695);font.draw(batch,"Host IP: "+address+"_",360,630);font.draw(batch,connected?"Host: "+session.partnerName():"Enter host IP and connect",360,560);font.draw(batch,connected?(clientReady?"READY":"READY UP"):"CONNECT",500,430);}font.setColor(Color.LIGHT_GRAY);font.draw(batch,status,360,350);font.setColor(Color.ORANGE);font.draw(batch,"LEAVE",500,245);batch.end();}
    @Override public void resize(int w,int h){viewport.update(w,h,true);}@Override public void hide(){}@Override public void pause(){}@Override public void resume(){}@Override public void dispose(){font.dispose();batch.dispose();shapes.dispose();}
}
